def maximize_discharge(M, S, steps):
    result = list(steps)
    mask = (1 << S) - 1

    for i in range(M-1, -1, -1):
        if steps[i] == 'x':
            if i > 0 and result[i-1] == '+':
                result[i-1] = 'o'
                continue
        power = 1
        j = i
        while j < M and (steps[j] == '+' or steps[j] == 'x'):
            if steps[j] == '+':
                power += 1
            else:
                power *= 2
            power &= mask
            j += 1
        if power < ((1 << S) // 4):
            while i < j:
                result[i] = 'o'
                i += 1
    return ''.join(result)

