def optimize_spell(M, S, spell):
    max_power = 1 << S
    dp = [[False] * (max_power + 1) for _ in range(M + 1)]

    # Initialize dp array
    dp[0][1] = True

    # Fill dp array
    for i in range(1, M + 1):
        for p in range(max_power + 1):
            if dp[i - 1][p]:
                if spell[i - 1] == '+':
                    new_power = (p + 1) % max_power
                    dp[i][new_power] = True
                elif spell[i - 1] == 'x':
                    new_power = (p * 2) % max_power
                    dp[i][new_power] = True
                dp[i][p] = True

    # Backtrack to find the optimal spell
    result = [''] * M
    current_power = 1
    for i in range(M, 0, -1):
        if dp[i][current_power]:
            result[i - 1] = spell[i - 1]
        else:
            result[i - 1] = 'o'
        if spell[i - 1] == '+':
            current_power = (current_power - 1 + max_power) % max_power
        elif spell[i - 1] == 'x':
            current_power = (current_power // 2) % max_power

    return ''.join(result)

def max_power_discharge(M, S, steps):
    # Initialize variables
    result = list(steps)
    current_power = 1

    # Iterate through each step
    for i in range(M):
        if steps[i] == '+':
            current_power += 1
        elif steps[i] == 'x':
            current_power *= 2

        # Check if we need to replace a step with 'o'
        if current_power >= 2**S:
            while current_power >= 2**S:
                if steps[i] == '+':
                    current_power -= 1
                    result[i] = 'o'
                elif steps[i] == 'x':
                    current_power //= 2
                    result[i] = 'o'

    return ''.join(result)

