def max_power_discharge(M, S, steps):
    def can_use_step(step, power):
        return (step == 'x' and power % 2 == 0) or (step == '+' and power < 2**S)

    result = []
    current_power = 1

    for step in steps:
        if can_use_step(step, current_power):
            result.append(step)
            if step == '+':
                current_power += 1
            else:
                current_power *= 2
        else:
            result.append('o')

    return ''.join(result)

