    for i in range(M):
        if spell[i] == '+':
            power += 1
        elif spell[i] == 'x':
            power *= 2

        # Check if we need to replace this operation with 'o'
        if power > (1 << S):
            if i + 1 < M and spell[i + 1] == '+':
                power -= 1
                result.append('o')
            else:
                power //= 2
                result.append('o')
        else:
            result.append(spell[i])

    return ''.join(result)

